#!/usr/bin/env node
// Disposable TLS terminator for the browser-SSO preview
// (docs/ecosystem/host-policy.md §7): terminates https://id.localhost:<port>
// with a self-signed cert generated by scripts/ecosystem-sso-verify.mjs and
// forwards to the plain-HTTP API on loopback. It only carries the issuer
// surface — /oauth2/**, /.well-known/**, /connect/logout, /login,
// /api/v1/auth/** — so X-Forwarded-Proto/Host are stamped for SAS issuer
// context validation (the scoped ForwardedHeaderFilter owns those paths).
//
//   node scripts/dev-id-tls.mjs --key <key.pem> --cert <cert.pem> \
//     --port 4443 --target http://127.0.0.1:4100

import fs from 'node:fs';
import http from 'node:http';
import https from 'node:https';
import { URL } from 'node:url';

function parseArgs(argv) {
  const args = { port: 4443, target: 'http://127.0.0.1:4100', host: 'id.localhost' };
  for (let i = 0; i < argv.length; i += 1) {
    const a = argv[i];
    if (a === '--key') args.key = argv[++i];
    else if (a === '--cert') args.cert = argv[++i];
    else if (a === '--port') args.port = Number(argv[++i]);
    else if (a === '--target') args.target = argv[++i];
    else if (a === '--host') args.host = argv[++i];
    else { console.error(`unknown arg ${a}`); process.exit(2); }
  }
  if (!args.key || !args.cert || !Number.isInteger(args.port)) {
    console.error('Usage: dev-id-tls.mjs --key <pem> --cert <pem> --port <n> --target <url>');
    process.exit(2);
  }
  return args;
}

const args = parseArgs(process.argv.slice(2));
const target = new URL(args.target);
const options = {
  key: fs.readFileSync(args.key),
  cert: fs.readFileSync(args.cert),
};

const server = https.createServer(options, (req, res) => {
  const upstream = http.request({
    hostname: target.hostname,
    port: target.port || 80,
    path: req.url,
    method: req.method,
    headers: {
      ...req.headers,
      host: `${args.host}:${args.port}`,
      'x-forwarded-proto': 'https',
      'x-forwarded-host': `${args.host}:${args.port}`,
      'x-real-ip': req.socket.remoteAddress || '',
    },
  }, (upstreamRes) => {
    res.writeHead(upstreamRes.statusCode || 502, upstreamRes.headers);
    upstreamRes.pipe(res);
  });
  upstream.on('error', (error) => {
    res.writeHead(502, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'UPSTREAM_UNREACHABLE' }));
  });
  req.pipe(upstream);
});

server.listen(args.port, '127.0.0.1', () => {
  console.log(`id-tls listening https://${args.host}:${args.port} -> ${args.target}`);
});
